package main

import (
	"encoding/json"
	"net/http/httptest"
	"testing"
	"time"
)

func TestProbeRemoveExpired(t *testing.T) {
	store := NewStore(30 * time.Second)
	now := time.Unix(1000, 0)
	store.now = func() time.Time { return now }
	store.Create("a", "u1")
	now = time.Unix(1020, 0)
	store.Create("b", "u2")

	now = time.Unix(1035, 0) // a expired, b live
	removed := store.RemoveExpired()
	if removed != 1 {
		t.Fatalf("removed = %d, want 1", removed)
	}
	if store.Len() != 1 {
		t.Fatalf("len = %d, want 1", store.Len())
	}
	if _, err := store.Get("a"); err == nil {
		t.Fatal("expired session survived RemoveExpired")
	}
	if _, err := store.Get("b"); err != nil {
		t.Fatalf("live session removed by mistake: %v", err)
	}

	// Second call: nothing to remove.
	if removed := store.RemoveExpired(); removed != 0 {
		t.Fatalf("second removed = %d, want 0", removed)
	}

	// /healthz reflects the sweep: create an expired one, healthz drops it.
	now = time.Unix(1040, 0)
	store.Create("c", "u3")
	now = time.Unix(1075, 0) // c expired (1040+30=1070 < 1075)
	handler := healthHandler(store)
	rec := httptest.NewRecorder()
	handler(rec, httptest.NewRequest("GET", "/healthz", nil))
	var body map[string]int
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("healthz body: %v", err)
	}
	if body["sessions"] != 0 {
		t.Fatalf("healthz sessions = %d, want 0 after auto-sweep", body["sessions"])
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_remove_test.go ; exit $rc

